foreach ($file in $targets) {
  if (-not (Test-Path $file.FullName)) { continue }
  $t = [IO.File]::ReadAllText($file.FullName, $utf8)
  $o = $t
  foreach ($pair in $pairs) { $t = $t.Replace($pair[0], $pair[1]) }
  if ($t -ne $o) {
    for ($i = 0; $i -lt 5; $i++) { try { [IO.File]::WriteAllText($file.FullName, $t, $utf8); break } catch { Start-Sleep -Milliseconds 300 } }
    Write-Host "OK: $($file.Name)"
  }
}
